#include <stdio.h>

// Generated by deepseek, for testing pointer declarations and type qualifiers

int main() {
    char a[4][3][2] = {{{'a', 'b'}, {'c', 'd'}, {'e', 'f'}},
                       {{'g', 'h'}, {'i', 'j'}, {'k', 'l'}},
                       {{'m', 'n'}, {'o', 'p'}, {'q', 'r'}},
                       {{'s', 't'}, {'u', 'v'}, {'w', 'x'}}};
    
    char (*pa)[2] = &a[1][0];      // pa指向包含2个char的一维数组
    char (*ppa)[3][2] = &a[1];     // ppa指向包含3×2个char的二维数组
    
    // 要访问'r'元素，它在a[2][2][1]位置
    // 因为：第3个二维数组(索引2) -> 第3个一维数组(索引2) -> 第2个元素(索引1)
    
    printf("直接访问: a[2][2][1] = %c\n", a[2][2][1]);
    
    // 通过pa访问'r'
    // pa指向a[1][0]，即第2个二维数组的第1个一维数组
    // 需要偏移：
    // - 先跳过第2个二维数组的剩余部分到a[1][2][1]
    // - 再跳过整个第3个二维数组到a[2][2][1]
    printf("pa[0][0]=%c, pa[0][1]=%c\n", pa[0][0], pa[0][1]);
    printf("pa[1][0]=%c, pa[1][1]=%c\n", pa[1][0], pa[1][1]);
    printf("pa[2][0]=%c, pa[2][1]=%c\n", pa[2][0], pa[2][1]);
    printf("pa[3][0]=%c, pa[3][1]=%c\n", pa[3][0], pa[3][1]);
    printf("pa[4][0]=%c, pa[4][1]=%c\n", pa[4][0], pa[4][1]);
    printf("pa[5][0]=%c, pa[5][1]=%c\n", pa[5][0], pa[5][1]);
    printf("所以pa[4][1] = %c 是'r'\n\n", pa[4][1]);
    
    // 通过ppa访问'r'
    // ppa指向a[1]，即整个第2个二维数组
    printf("通过ppa访问: ppa[1][2][1]\n");
    printf("ppa[0][0][0]=%c, ppa[0][0][1]=%c\n", ppa[0][0][0], ppa[0][0][1]);
    printf("ppa[0][1][0]=%c, ppa[0][1][1]=%c\n", ppa[0][1][0], ppa[0][1][1]);
    printf("ppa[0][2][0]=%c, ppa[0][2][1]=%c\n", ppa[0][2][0], ppa[0][2][1]);
    printf("ppa[1][0][0]=%c, ppa[1][0][1]=%c\n", ppa[1][0][0], ppa[1][0][1]);
    printf("ppa[1][1][0]=%c, ppa[1][1][1]=%c\n", ppa[1][1][0], ppa[1][1][1]);
    printf("ppa[1][2][0]=%c, ppa[1][2][1]=%c\n", ppa[1][2][0], ppa[1][2][1]);
    printf("所以ppa[1][2][1] = %c 是'r'\n", ppa[1][2][1]);
    
    return 0;
}